package com.manishrawat.realestate.dao;
import com.manishrawat.realestate.model.User; import com.manishrawat.realestate.util.DBConnection; import java.sql.*; import java.util.*;
public class MessageDAO {
 public List<Map<String,Object>> contacts(User u)throws Exception{String sql="SELECT DISTINCT x.id,x.name,x.role FROM (SELECT CASE WHEN a.tenant_id=? THEN p.manager_id ELSE a.tenant_id END contact_id FROM rental_applications a JOIN properties p ON p.id=a.property_id WHERE a.tenant_id=? OR p.manager_id=?) rel JOIN users x ON x.id=rel.contact_id WHERE x.id IS NOT NULL ORDER BY x.name";List<Map<String,Object>> rows=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,u.getId());p.setInt(2,u.getId());p.setInt(3,u.getId());try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object>m=new LinkedHashMap<>();m.put("id",r.getInt("id"));m.put("name",r.getString("name"));m.put("role",r.getString("role"));rows.add(m);}}}return rows;}
 public List<Map<String,Object>> conversation(int a,int b)throws Exception{String sql="SELECT m.id,m.sender_id,m.receiver_id,m.message,m.sent_at,u.name sender_name FROM messages m JOIN users u ON u.id=m.sender_id WHERE (m.sender_id=? AND m.receiver_id=?) OR (m.sender_id=? AND m.receiver_id=?) ORDER BY m.id";List<Map<String,Object>> rows=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,a);p.setInt(2,b);p.setInt(3,b);p.setInt(4,a);try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object>x=new LinkedHashMap<>();for(String k:List.of("id","sender_id","receiver_id","message","sent_at","sender_name"))x.put(k,r.getObject(k));rows.add(x);}}}return rows;}
 public boolean canContact(int a,int b)throws Exception{String sql="SELECT 1 FROM rental_applications a JOIN properties p ON p.id=a.property_id WHERE (a.tenant_id=? AND p.manager_id=?) OR (a.tenant_id=? AND p.manager_id=?) LIMIT 1";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,a);p.setInt(2,b);p.setInt(3,b);p.setInt(4,a);try(ResultSet r=p.executeQuery()){return r.next();}}}
 public void send(int sender,int receiver,String text)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO messages(sender_id,receiver_id,message) VALUES(?,?,?)")){p.setInt(1,sender);p.setInt(2,receiver);p.setString(3,text);p.executeUpdate();}}
}
